import {clamp,distance,geography,normal,move,terrain,HALF,PLANET_RADIUS as R,wrap} from './planet.js';
const cross=(a,b)=>({x:a.y*b.z-a.z*b.y,y:a.z*b.x-a.x*b.z,z:a.x*b.y-a.y*b.x});
const dot=(a,b)=>a.x*b.x+a.y*b.y+a.z*b.z;
export class Geology {
 constructor(sim,saved){this.sim=sim;this.revision=0;this.nextId=1;this.totals={quakes:0,eruptions:0,extruded:0,weathered:0};this.cells=sim.environment.geo.map(()=>({uplift:0,erosion:0,ash:0}));this.quakes=[];this.lava=[];this.plates=[];this.faults=[];this.vents=[];if(saved){this.accept(saved);return;}
  let seed=(sim.worldSeed^0x729d31)>>>0;const random=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};
  this.plates=Array.from({length:6},(_,i)=>({id:i,n:normal((i/6*2-1)*HALF+random()*20,Math.asin((i%2?1:-1)*(.2+random()*.5))*R),axis:normal(random()*2*HALF-HALF,(random()-.5)*100)}));
  const geo=sim.environment.geo;this.membership=geo.map(g=>this.plates.reduce((best,p)=>dot(p.n,g.n)>dot(this.plates[best].n,g.n)?p.id:best,0));const pairs=new Map();
  for(let i=0;i<geo.length;i++)for(const j of geo[i].neighbors){if(i>=j||this.membership[i]===this.membership[j])continue;const a=this.membership[i],b=this.membership[j],key=[a,b].sort().join('-'),list=pairs.get(key)||[];if(list.length>=2||list.some(f=>distance(f,geo[i])<18))continue;const va=cross(this.plates[a].axis,geo[i].n),vb=cross(this.plates[b].axis,geo[i].n),dir={x:geo[j].n.x-geo[i].n.x,y:geo[j].n.y-geo[i].n.y,z:geo[j].n.z-geo[i].n.z},len=Math.hypot(dir.x,dir.y,dir.z),closing=dot({x:va.x-vb.x,y:va.y-vb.y,z:va.z-vb.z},dir)/len;const f={id:this.faults.length,i,j,a,b,x:geo[i].x,z:geo[i].z,type:closing>.25?'convergente':closing<-.25?'divergente':'transformante',loading:.0006+Math.abs(closing)*.0006,stress:.2+random()*.45,threshold:1+random()*.4,last:-1};this.faults.push(f);list.push(f);pairs.set(key,list);}
  for(const f of this.faults)if(f.type!=='transformante'&&this.vents.length<8){const candidates=[f.i,f.j,...geo[f.i].neighbors,...geo[f.j].neighbors];const site=candidates.map(i=>geo[i]).find(g=>g.land&&!g.river&&g.height>.3&&this.vents.every(v=>distance(v,g)>12));if(site)this.vents.push({id:this.vents.length,fault:f.id,x:site.x,z:site.z,magma:1.8,capacity:3,influx:f.loading*2,erupting:false,cone:.15,radius:2.3,emitClock:0,rock:0});}
 }
 snapshot(){return Object.fromEntries(['revision','nextId','totals','cells','plates','membership','faults','vents','quakes','lava'].map(k=>[k,this[k]]));}
 accept(s){for(const k of Object.keys(s))this[k]=s[k];}
 weights(x,z){const u=(wrap(x)+HALF)/(2*HALF)*32-.5,v=clamp((Math.sin(z/R)+1)*8-.5,0,15),a=Math.floor(u),b=Math.floor(v),fx=u-a,fy=v-b;return [0,1,2,3].map(k=>({i:Math.min(15,b+(k>>1))*32+((a+(k%2)+32)%32),w:(k%2?fx:1-fx)*(k>>1?fy:1-fy)}));}
 offset(x,z){let h=0;for(const {i,w} of this.weights(x,z))h+=(this.cells[i].uplift+this.cells[i].erosion)*w;return h;}
 coneHeight(x,z){let h=0;for(const v of this.vents){const d=distance(v,{x,z});if(d<v.radius)h+=v.cone*clamp((1-d/v.radius)/.78,0,1);}return h;}
 groundHeight(x,z){const g=geography(x,z);return g.land?Math.max(.03,g.height+this.offset(x,z))+this.coneHeight(x,z):terrain(x,z);}
 cellHeight(i){const g=this.sim.environment.geo[i];return g.land?Math.max(.03,g.height+this.offset(g.x,g.z))+this.coneHeight(g.x,g.z):Math.min(-.03,g.height+this.offset(g.x,g.z));}
 heat(x,z){let risk=0;for(const l of this.lava)if(l.heat>.08)risk=Math.max(risk,l.heat*Math.max(0,1-distance(l,{x,z})/l.radius));return risk;}
 risk(x,z,c){return this.heat(x,z)+(c?.species===5?0:Math.max(0,(this.sim.hydrology?.floodAt(x,z)||0)-.16-(c?.dna.traits.webbing??.3)*.45));}
 evacuate(c,state){const sim=this.sim;sim.recovery?.wake(c,'el terreno se vuelve peligroso');sim.cancelPair(c);c.emergencyUntil=sim.time+3;c.state=state;c.think=3;let best=this.risk(c.x,c.z,c),target=c.target;for(let k=0;k<12;k++){const p=move(c.x,c.z,Math.sin(k*Math.PI/6)*4,Math.cos(k*Math.PI/6)*4),risk=this.risk(p.x,p.z,c);if(risk<best&&sim.habitatValid(p.x,p.z,c.species,c)&&!sim.culture.blocked(p.x,p.z)){best=risk;target={...p,kind:'escape'};}}c.target=target;}
 earthquake(f,time){const strength=f.stress;f.stress*=.18;f.last=time;this.totals.quakes++;this.quakes.push({id:this.nextId++,x:f.x,z:f.z,time,strength,fault:f.id});this.quakes=this.quakes.slice(-12);for(const [i,sign] of [[f.i,f.type==='divergente'?-1:1],[f.j,-1]])this.cells[i].uplift=clamp(this.cells[i].uplift+sign*strength*(f.type==='transformante'?.015:.08),-.6,.8);for(const b of this.sim.culture.blocks){const exposure=Math.max(0,1-distance(b,f)/10);b.health-=strength*exposure*.5;}for(const c of this.sim.creatures){const exposure=Math.max(0,1-distance(c,f)/8);if(exposure){c.health-=strength*exposure*12;c.environmentCause='murió durante un terremoto';this.evacuate(c,'Sobresaltado por el sismo');}}this.sim.log('Una falla '+f.type+' libera tensión y sacude el terreno.','⌁','earthquake',null,f);}
 advance(dt,time){this.revision++;for(const f of this.faults){f.stress+=f.loading*dt;if(f.stress>=f.threshold)this.earthquake(f,time);}this.quakes=this.quakes.filter(q=>time-q.time<12);
  let active=this.vents.filter(v=>v.erupting).length;for(const v of this.vents){v.magma+=v.influx*dt;if(!v.erupting&&v.magma>=v.capacity&&active<2){v.erupting=true;active++;this.totals.eruptions++;this.sim.log('El reservorio del volcán '+(v.id+1)+' supera su presión de salida. Comienza una erupción.','▲','eruption',null,v);}if(!v.erupting)continue;const mass=Math.min(v.magma,.025*dt);v.magma-=mass;v.rock+=mass*.65;v.cone=.15+Math.min(1.8,v.rock*.18);this.cells[this.sim.environment.index(v.x,v.z)].ash+=mass*.35;this.totals.extruded+=mass;v.emitClock+=dt;
   if(v.emitClock>=6){v.emitClock-=6;let p=move(v.x,v.z,v.radius,0),h=this.groundHeight(p.x,p.z);for(let k=1;k<12;k++){const q=move(v.x,v.z,Math.sin(k*Math.PI/6)*v.radius,Math.cos(k*Math.PI/6)*v.radius),height=this.groundHeight(q.x,q.z);if(height<h){p=q;h=height;}}const old=this.lava.find(l=>l.vent===v.id&&distance(l,p)<1);if(old)old.heat=1;else{if(this.lava.length>=48)this.lava.shift();this.lava.push({...p,id:this.nextId++,vent:v.id,heat:1,radius:1.8,time});}}
   if(v.magma<v.capacity*.2){v.erupting=false;active--;this.sim.log('El volcán '+(v.id+1)+' se aquieta; la lava pierde calor y permanece la roca.','△','eruption',null,v);}}
  for(const l of this.lava)l.heat*=Math.exp(-dt/70);for(let i=0;i<this.cells.length;i++){const c=this.cells[i],g=this.sim.environment.geo[i],wet=this.sim.environment.cells[i].soil,amount=c.ash*(1-Math.exp(-dt*.0008*wet));if(amount>1e-9){c.ash-=amount;this.totals.weathered+=amount;this.sim.deposit(g.x,g.z,amount,'Meteorización de ceniza');}}
 }
 exposure(){for(const c of this.sim.creatures){const heat=this.heat(c.x,c.z);if(heat>.12){c.health-=heat*16;c.environmentCause='murió por el calor de la lava';this.evacuate(c,'Huyendo de la lava');}}for(const p of this.sim.food){const heat=this.heat(p.x,p.z);if(heat>.1){const mass=Math.min(p.biomass,heat*.08);p.biomass-=mass;p.growth=Math.max(0,p.growth-heat*.08);this.sim.deposit(p.x,p.z,mass,'Vegetación quemada');}}for(const b of this.sim.culture.blocks)b.health-=this.heat(b.x,b.z)*.08;}
}
